import { createTestClient, erc20Abi, erc4626Abi, maxUint256, publicActions, walletActions, } from "viem";
import { sendRawTransaction as viem_sendRawTransaction, sendTransaction as viem_sendTransaction, writeContract as viem_writeContract, } from "viem/actions";
import { dealActions } from "viem-deal";
import { traceActions, traced, } from "viem-tracer";
import { testAccount } from "./fixtures.js";
import { getFunctionCalls, } from "./utils/getFunctionCalls.js";
export const createAnvilTestClient = (transport, chain) => createTestClient({
    chain,
    mode: "anvil",
    account: testAccount(),
    transport: traced(transport),
    cacheTime: Number.POSITIVE_INFINITY,
})
    .extend(dealActions)
    .extend(traceActions)
    .extend(publicActions)
    .extend(walletActions)
    .extend((client) => {
    let automine;
    return {
        async timestamp() {
            const latestBlock = await client.getBlock();
            return latestBlock.timestamp;
        },
        async approve(args) {
            args.abi = erc20Abi;
            args.functionName = "approve";
            // @ts-expect-error
            return this.writeContract(args);
        },
        async balanceOf({ erc20 = "0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE", owner = client.account.address, } = {}) {
            if (erc20 === "0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE")
                return client.getBalance({ address: owner });
            return client.readContract({
                address: erc20,
                abi: erc20Abi,
                functionName: "balanceOf",
                args: [owner],
            });
        },
        async allowance({ erc20 = "0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE", owner = client.account.address, spender, }) {
            if (erc20 === "0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE")
                return maxUint256;
            return client.readContract({
                address: erc20,
                abi: erc20Abi,
                functionName: "allowance",
                args: [owner, spender],
            });
        },
        async maxWithdraw({ erc4626, owner = client.account.address, }) {
            return client.readContract({
                address: erc4626,
                abi: erc4626Abi,
                functionName: "maxWithdraw",
                args: [owner],
            });
        },
        async previewMint({ erc4626, shares, }) {
            return client.readContract({
                address: erc4626,
                abi: erc4626Abi,
                functionName: "previewMint",
                args: [shares],
            });
        },
        async convertToShares({ erc4626, assets, }) {
            return client.readContract({
                address: erc4626,
                abi: erc4626Abi,
                functionName: "convertToShares",
                args: [assets],
            });
        },
        async convertToAssets({ erc4626, shares, }) {
            return client.readContract({
                address: erc4626,
                abi: erc4626Abi,
                functionName: "convertToAssets",
                args: [shares],
            });
        },
        async deposit(args) {
            args.abi = erc4626Abi;
            args.functionName = "deposit";
            // @ts-expect-error
            return this.writeContract(args);
        },
        async deployContractWait(args) {
            const hash = await client.deployContract(args);
            const receipt = await client.waitForTransactionReceipt({ hash });
            if (receipt.contractAddress == null)
                throw Error("no contract address");
            return receipt;
        },
        async writeContract(args) {
            const hash = await viem_writeContract(client, args);
            if ((automine ??= await client.getAutomine()))
                await client.waitForTransactionReceipt({ hash });
            return hash;
        },
        async sendTransaction(args) {
            const hash = await viem_sendTransaction(client, args);
            if ((automine ??= await client.getAutomine()))
                await client.waitForTransactionReceipt({ hash });
            return hash;
        },
        async sendRawTransaction(args) {
            const hash = await viem_sendRawTransaction(client, args);
            if ((automine ??= await client.getAutomine()))
                await client.waitForTransactionReceipt({ hash });
            return hash;
        },
        getFunctionCalls(args) {
            return getFunctionCalls(client, args);
        },
    };
});
